cypress_script:
describe('JavaScript Alerts', () => {
  it('should show a JS Alert and dismiss it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (str) => {
      expect(str).to.equal('I am a JS Alert');
    });
    cy.url().should('eq', 'https://the-internet.herokuapp.com/javascript_alerts');
  });

  it('should show a JS Confirm and not change the URL', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Confirm').click();
    cy.on('window:confirm', () => true);
    cy.url().should('eq', 'https://the-internet.herokuapp.com/javascript_alerts');
    cy.get('#result').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts', () => {
  test('should show a JS Alert and dismiss it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.dismiss();
    });
    await page.click('text=Click for JS Alert');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/javascript_alerts');
  });

  test('should show a JS Confirm and not change the URL', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    page.on('dialog', async dialog => {
      await dialog.accept();
    });
    await page.click('text=Click for JS Confirm');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/javascript_alerts');
    await expect(page.locator('#result')).toBeVisible();
  });
});
